<p id="testResults"></p>
<script>
const shoppingList = ["apples", "bread", "milk", "cheese"];

function findItem(itemName) {
for (let i = 0; i < shoppingList.length; i++) {
if (shoppingList[i] == itemName) {
return true;
}
```

